9	}
10	
11	const PROCESSING_FEE = 5;
12	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
13	const LOYALTY_DISCOUNT_RATE = 0.2;
14	const LOYALTY_YEARS_THRESHOLD = 2;
15	
16	const BASE_PREMIUMS: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	};
24	
25	const CURSE_SURCHARGE_RATE = 0.5;
26	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
27	const HIGH_ENCHANTMENT_THRESHOLD = 5;
28	const COMPONENT_BLOCK_SIZE = 3;
29	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
30	
31	// "Alike" means the same item type: 2 runes + 1 moonstone form no block,
32	// while 3 runes + 3 moonstones form two separate blocks.
33	function groupAlikeItems(items: Item[]): Map<string, number> {
34	  const countsPerAlikeGroup = new Map<string, number>();
35	  for (const item of items) {
36	    countsPerAlikeGroup.set(item.type, (countsPerAlikeGroup.get(item.type) ?? 0) + 1);
37	  }
38	  return countsPerAlikeGroup;
39	}
40	
41	function qualifiesForComponentBlock(count: number): boolean {
42	  return count === COMPONENT_BLOCK_SIZE;
43	}
44	
45	function basePremiumForAlikeGroup(type: string, count: number): number {
46	  if (qualifiesForComponentBlock(count)) {
47	    return COMPONENT_BLOCK_BASE_PREMIUM;
48	  }
49	  return count * BASE_PREMIUMS[type];
50	}
51	
52	function isHighlyEnchanted(item: Item): boolean {
53	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
54	}
55	
56	// Item-specific modifiers apply to the base premium of the affected item,
57	// not to the policy total.
58	function itemSurcharges(item: Item): number {
59	  const listedBasePremium = BASE_PREMIUMS[item.type];
60	  let surcharges = 0;
61	  if (item.cursed === true) {
62	    surcharges += listedBasePremium * CURSE_SURCHARGE_RATE;
63	  }
64	  if (isHighlyEnchanted(item)) {
65	    surcharges += listedBasePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE;
66	  }
67	  return surcharges;
68	}
69	
70	// The spec's "policy base premium": the sum of all item base premiums,
71	// before any item-specific or policy-wide modifier.
72	function policyBasePremium(items: Item[]): number {
73	  let total = 0;
74	  for (const [type, count] of groupAlikeItems(items)) {
75	    total += basePremiumForAlikeGroup(type, count);
76	  }
77	  return total;
78	}
79	
80	function totalItemSurcharges(items: Item[]): number {
81	  return items.reduce((total, item) => total + itemSurcharges(item), 0);
82	}
83	
84	function isLongStandingCustomer(customer: Customer): boolean {
85	  return customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
86	}
87	
88	// Policy-wide modifiers are percentages of the policy base premium itself,
89	// not of the premium already raised by item-specific surcharges.
90	function policyModifiers(customer: Customer, basePremium: number): number {
91	  let modifiers = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
92	  if (isLongStandingCustomer(customer)) {
93	    modifiers -= basePremium * LOYALTY_DISCOUNT_RATE;
94	  }
95	  return modifiers;
96	}
97	
98	function roundPremiumInMHPCOsFavour(premium: number): number {
99	  return Math.ceil(premium);
100	}
101	
102	export function quote(customer: Customer, items: Item[]): number {
103	  const basePremium = policyBasePremium(items);
104	  const premium =
105	    basePremium +
106	    totalItemSurcharges(items) +
107	    policyModifiers(customer, basePremium) +
108	    PROCESSING_FEE;
109	  return roundPremiumInMHPCOsFavour(premium);
110	}
